def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    marker = next(
        (v for row in grid for v in row if v != next(iter(
            {x for r in grid for x in r if sum(rr.count(x) for rr in grid) > 0}
        ))),
        None
    )
    # The background is the most common color; all other cells are markers.
    from collections import Counter
    bg = Counter(x for row in grid for x in row).most_common(1)[0][0]
    marks = [(r, c) for r in range(h) for c in range(w) if grid[r][c] != bg]

    for r in range(h):
        cols = [c for rr, c in marks if rr == r]
        if len(cols) >= 2:
            for c in range(min(cols), max(cols) + 1):
                if grid[r][c] == bg:
                    out[r][c] = 3

    for c in range(w):
        rows = [r for r, cc in marks if cc == c]
        if len(rows) >= 2:
            for r in range(min(rows), max(rows) + 1):
                if grid[r][c] == bg:
                    out[r][c] = 3

    return out
